 when s->>'skillId'~'^(?:listen_main_idea|listen_inference|main_idea|inference)$' and (s->>'level')::integer=1 then 4
 when s->>'skillId'~'^(?:listen_theme|theme|informational_features|literary_craft)$' and (s->>'level')::integer=1 then 5
 when s->>'skillId'~'^(?:listen_key_details|key_details)$' and (s->>'level')::integer=2 then 5
 when s->>'skillId'~'^(?:listen_sequencing|listen_main_idea|listen_inference|listen_cause_effect|listen_theme|sequencing|main_idea|inference|cause_effect|theme|informational_features|literary_craft)$' and (s->>'level')::integer=2 then 6
 when s->>'skillId'~'^(?:nouns|verbs)$' and (s->>'level')::integer=1 then 2
 when s->>'skillId'~'^(?:prepositions)$' and (s->>'level')::integer=1 and s->>'constructClaim'~'^(in|on|under|behind|next_to|above|below)$' then 2
 when s->>'skillId'~'^(?:adjectives|plurals|sentence_comprehension)$' and (s->>'level')::integer=1 then 3
 when s->>'skillId'~'^(?:nouns|verbs|adjectives|prepositions)$' and (s->>'level')::integer=2 then 4
 when s->>'skillId'~'^(?:plurals|sentence_comprehension)$' and (s->>'level')::integer=2 then 5
 when s->>'skillId'~'^(?:capitalization)$' and (s->>'level')::integer=1 and s->>'constructClaim'~'^sentence_capital$' then 1
 when s->>'skillId'~'^(?:writing_organization)$' and (s->>'level')::integer=1 and s->>'constructClaim'~'^sentence_word_order$' then 2
 when s->>'skillId'~'^(?:writing_revision)$' and (s->>'level')::integer=1 and s->>'constructClaim'~'^complete_sentence$' then 2
 when s->>'skillId'~'^(?:punctuation|writing_purpose)$' and (s->>'level')::integer=1 then 3
 when s->>'skillId'~'^(?:writing_organization|writing_revision)$' and (s->>'level')::integer=1 then 4
 when s->>'skillId'~'^(?:capitalization|punctuation|writing_purpose|writing_organization|writing_revision)$' and (s->>'level')::integer=2 then 5 else null end end band from source),
 snapshots as (select item,s||jsonb_build_object('contentVersion','literacy-mock-v5','adaptiveAreaVersion','areas-v1','adaptiveAreaBand',band,'adaptiveMixedEligible',band is not null) snapshot from classified)
insert into literacy_mock_incoming select jsonb_set(item,'{itemSnapshot}',snapshot) from snapshots;
do $$begin
 if (select count(*) from public.literacy_mock_items where content_version='literacy-mock-v4')<>8819 then raise exception 'Unexpected v4 publication'; end if;
 if (select count(*) from literacy_mock_incoming)<>9094 then raise exception 'Incomplete v5 publication'; end if;
 if exists(select 1 from literacy_mock_incoming incoming join public.literacy_mock_items old on old.id=incoming.item->>'id' and old.content_version='literacy-mock-v5' where old.item is distinct from incoming.item) then raise exception 'Cannot rewrite immutable v5 publication'; end if;
end; $$;
insert into public.literacy_mock_items(id,content_version,item) select item->>'id','literacy-mock-v5',item from literacy_mock_incoming on conflict(id,content_version) do nothing;
insert into public.literacy_mock_publications(content_version,item_count) values('literacy-mock-v5',9094) on conflict(content_version) do nothing;
do $$begin
 if (select count(*) from public.literacy_mock_items where content_version='literacy-mock-v5')<>9094
 or not exists(select 1 from public.literacy_mock_publications where content_version='literacy-mock-v5' and item_count=9094) then raise exception 'Publication count mismatch'; end if;
end; $$;
commit;
